package org.apache.lucene.document;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import org.apache.lucene.geo.Polygon;
import org.apache.lucene.geo.Tessellator;

/**
 * Brute-force search for flat polygons whose tessellation produces triangles that are simplified to
 * LINEs at query time with an edge flag that does not match the actual polygon boundary.
 */
public class FlagSearch {

  static final double EPS = 1e-9;

  static int orient(double ax, double ay, double bx, double by, double cx, double cy) {
    double v = (bx - ax) * (cy - ay) - (by - ay) * (cx - ax);
    if (Math.abs(v) < 1e-12) return 0;
    return v > 0 ? 1 : -1;
  }

  static boolean onSegment(double ax, double ay, double bx, double by, double px, double py) {
    return orient(ax, ay, bx, by, px, py) == 0
        && Math.min(ax, bx) <= px
        && px <= Math.max(ax, bx)
        && Math.min(ay, by) <= py
        && py <= Math.max(ay, by);
  }

  /** positive-length overlap between two segments */
  static boolean segmentsOverlap(
      double ax, double ay, double bx, double by, double cx, double cy, double dx, double dy) {
    // both endpoints of cd on line ab and vice versa (collinear), plus bbox overlap
    if (orient(ax, ay, bx, by, cx, cy) != 0 || orient(ax, ay, bx, by, dx, dy) != 0) {
      return false;
    }
    // positive length intersection required
    double lox = Math.max(Math.min(ax, bx), Math.min(cx, dx));
    double hix = Math.min(Math.max(ax, bx), Math.max(cx, dx));
    double loy = Math.max(Math.min(ay, by), Math.min(cy, dy));
    double hiy = Math.min(Math.max(ay, by), Math.max(cy, dy));
    if (lox > hix || loy > hiy) return false;
    if (hix - lox > EPS) return true;
    return hiy - loy > EPS;
  }

  static boolean overlapsBoundary(Polygon p, double ax, double ay, double bx, double by) {
    List<Polygon> all = new ArrayList<>();
    all.add(p);
    for (Polygon h : p.getHoles()) {
      all.add(h);
    }
    for (Polygon poly : all) {
      double[] lats = poly.getPolyLats();
      double[] lons = poly.getPolyLons();
      for (int i = 1; i < lats.length; i++) {
        if (segmentsOverlap(
            lons[i - 1], lats[i - 1], lons[i], lats[i], ax, ay, bx, by)) {
          return true;
        }
      }
    }
    return false;
  }

  static String check(Polygon polygon) {
    List<Tessellator.Triangle> tess = Tessellator.tessellate(polygon);
    int bad = 0;
    int over = 0;
    for (Tessellator.Triangle t : tess) {
      byte[] bytes = new byte[7 * 4];
      ShapeField.encodeTriangle(
          bytes,
          t.getEncodedY(0),
          t.getEncodedX(0),
          t.isEdgefromPolygon(0),
          t.getEncodedY(1),
          t.getEncodedX(1),
          t.isEdgefromPolygon(1),
          t.getEncodedY(2),
          t.getEncodedX(2),
          t.isEdgefromPolygon(2));
      ShapeField.DecodedTriangle dt = new ShapeField.DecodedTriangle();
      ShapeField.decodeTriangle(bytes, dt);
      ShapeField.resolveTriangleType(dt);
      if (dt.type == ShapeField.DecodedTriangle.TYPE.LINE) {
        double ax = org.apache.lucene.geo.GeoEncodingUtils.decodeLongitude(dt.aX);
        double ay = org.apache.lucene.geo.GeoEncodingUtils.decodeLatitude(dt.aY);
        double bx = org.apache.lucene.geo.GeoEncodingUtils.decodeLongitude(dt.bX);
        double by = org.apache.lucene.geo.GeoEncodingUtils.decodeLatitude(dt.bY);
        boolean overlap = overlapsBoundary(polygon, ax, ay, bx, by);
        if (overlap && dt.ab == false) {
          bad++;
        }
        if (overlap == false && dt.ab == true) {
          over++;
        }
      }
    }
    return bad + " " + over;
  }

  static Polygon randomPolygon(Random r) {
    int n = 6 + r.nextInt(10);
    // base circle radius 1-10 degrees
    double cx = (r.nextDouble() - 0.5) * 40;
    double cy = (r.nextDouble() - 0.5) * 80;
    double radius = 1 + r.nextDouble() * 5;
    List<double[]> pts = new ArrayList<>();
    double prevAngle = -1;
    for (int i = 0; i < n; i++) {
      double angle = r.nextDouble() * 2 * Math.PI;
      double rad = radius * (0.5 + r.nextDouble());
      double lon = cx + rad * Math.cos(angle);
      double lat = cy + rad * Math.sin(angle);
      pts.add(new double[] {lon, lat});
      // with some probability add a cluster of quantization-flat points after this vertex
      if (r.nextInt(3) == 0) {
        int cluster = 1 + r.nextInt(3);
        // direction along towards previous point or next point
        double[] prev = pts.get(pts.size() - 1);
        double[] next;
        if (pts.size() > 1) {
          next = pts.get(pts.size() - 2);
        } else {
          next = new double[] {lon + rad * Math.cos(angle + 0.5), lat + rad * Math.sin(angle + 0.5)};
        }
        double dx = next[0] - prev[0];
        double dy = next[1] - prev[1];
        double len = Math.sqrt(dx * dx + dy * dy);
        dx /= len;
        dy /= len;
        for (int j = 1; j <= cluster; j++) {
          double step = j * r.nextDouble() * 1e-7; // sub-quantization steps
          pts.add(new double[] {prev[0] + dx * step, prev[1] + dy * step});
        }
      }
    }
    double[] lats = new double[pts.size()];
    double[] lons = new double[pts.size()];
    for (int i = 0; i < pts.size(); i++) {
      lons[i] = pts.get(i)[0];
      lats[i] = pts.get(i)[1];
    }
    try {
      return new Polygon(lats, lons);
    } catch (Exception e) {
      return null;
    }
  }

  public static void main(String[] args) {
    Random r = new Random(Long.parseLong(args[0]));
    int found = 0;
    int overFound = 0;
    for (int i = 0; i < 20000; i++) {
      Polygon p = randomPolygon(r);
      if (p == null) continue;
      try {
        String res = check(p);
        if (!res.startsWith("0 ")) {
          System.out.println("BAD flags (" + res + "): " + polygonStr(p));
          found++;
        }
        if (!res.endsWith(" 0")) {
          overFound++;
        }
      } catch (Exception e) {
        // tessellation failure, ignore
      }
    }
    System.out.println("done, found=" + found + " overmarked=" + overFound);
  }

  static String polygonStr(Polygon p) {
    StringBuilder sb = new StringBuilder();
    double[] lats = p.getPolyLats();
    double[] lons = p.getPolyLons();
    for (int i = 0; i < lats.length; i++) {
      sb.append(lats[i]).append(",").append(lons[i]).append(" ");
    }
    return sb.toString();
  }
}

package org.apache.lucene.document;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import org.apache.lucene.geo.GeoEncodingUtils;
import org.apache.lucene.geo.Polygon;
import org.apache.lucene.geo.Tessellator;

/** stats of degenerate triangles */
public class Stats {

  static String check(Polygon polygon) {
    List<Tessellator.Triangle> tess = Tessellator.tessellate(polygon, false);
    StringBuilder sb = new StringBuilder();
    for (Tessellator.Triangle t : tess) {
      byte[] bytes = new byte[7 * 4];
      ShapeField.encodeTriangle(
          bytes,
          t.getEncodedY(0),
          t.getEncodedX(0),
          t.isEdgefromPolygon(0),
          t.getEncodedY(1),
          t.getEncodedX(1),
          t.isEdgefromPolygon(1),
          t.getEncodedY(2),
          t.getEncodedX(2),
          t.isEdgefromPolygon(2));
      ShapeField.DecodedTriangle dt = new ShapeField.DecodedTriangle();
      ShapeField.decodeTriangle(bytes, dt);
      String pre =
          "" + (dt.aX == dt.bX && dt.aY == dt.bY) + (dt.aX == dt.cX && dt.aY == dt.cY)
              + (dt.bX == dt.cX && dt.bY == dt.cY);
      ShapeField.resolveTriangleType(dt);
      if (dt.type == ShapeField.DecodedTriangle.TYPE.LINE) {
        sb.append(pre)
            .append(":")
            .append(dt.ab)
            .append(dt.bc)
            .append(dt.ca)
            .append(" ");
      } else if (dt.type == ShapeField.DecodedTriangle.TYPE.POINT) {
        sb.append("P ");
      }
    }
    return sb.toString();
  }

  static Polygon randomPolygon(Random r) {
    int n = 6 + r.nextInt(10);
    double cx = (r.nextDouble() - 0.5) * 40;
    double cy = (r.nextDouble() - 0.5) * 80;
    double radius = 1 + r.nextDouble() * 5;
    List<double[]> pts = new ArrayList<>();
    for (int i = 0; i < n; i++) {
      double angle = r.nextDouble() * 2 * Math.PI;
      double rad = radius * (0.5 + r.nextDouble());
      double lon = cx + rad * Math.cos(angle);
      double lat = cy + rad * Math.sin(angle);
      pts.add(new double[] {lon, lat});
      if (r.nextInt(3) == 0) {
        int cluster = 1 + r.nextInt(3);
        double[] prev = pts.get(pts.size() - 1);
        double[] next;
        if (pts.size() > 1) {
          next = pts.get(pts.size() - 2);
        } else {
          next = new double[] {lon + rad * Math.cos(angle + 0.5), lat + rad * Math.sin(angle + 0.5)};
        }
        double dx = next[0] - prev[0];
        double dy = next[1] - prev[1];
        double len = Math.sqrt(dx * dx + dy * dy);
        dx /= len;
        dy /= len;
        for (int j = 1; j <= cluster; j++) {
          double step = j * r.nextDouble() * 1e-7;
          pts.add(new double[] {prev[0] + dx * step, prev[1] + dy * step});
        }
      }
    }
    double[] lats = new double[pts.size()];
    double[] lons = new double[pts.size()];
    for (int i = 0; i < pts.size(); i++) {
      lons[i] = pts.get(i)[0];
      lats[i] = pts.get(i)[1];
    }
    try {
      return new Polygon(lats, lons);
    } catch (Exception e) {
      return null;
    }
  }

  public static void main(String[] args) {
    Random r = new Random(Long.parseLong(args[0]));
    int lineCount = 0;
    int polygons = 0;
    for (int i = 0; i < 20000; i++) {
      Polygon p = randomPolygon(r);
      if (p == null) continue;
      polygons++;
      try {
        String res = check(p);
        if (!res.isEmpty()) {
          lineCount++;
          if (lineCount < 10) {
            System.out.println("LINEs: " + res);
          }
        }
      } catch (Exception e) {
      }
    }
    System.out.println("polygons=" + polygons + " withDegenerate=" + lineCount);
  }
}

