package org.apache.lucene.document;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import org.apache.lucene.geo.GeoEncodingUtils;
import org.apache.lucene.geo.Polygon;
import org.apache.lucene.geo.Tessellator;

/** debug single polygons */
public class Debug {

  static int orient(double ax, double ay, double bx, double by, double cx, double cy) {
    double v = (bx - ax) * (cy - ay) - (by - ay) * (cx - ax);
    if (Math.abs(v) < 1e-12) return 0;
    return v > 0 ? 1 : -1;
  }

  static boolean segmentsOverlap(
      double ax, double ay, double bx, double by, double cx, double cy, double dx, double dy) {
    if (orient(ax, ay, bx, by, cx, cy) != 0 || orient(ax, ay, bx, by, dx, dy) != 0) {
      return false;
    }
    double lox = Math.max(Math.min(ax, bx), Math.min(cx, dx));
    double hix = Math.min(Math.max(ax, bx), Math.max(cx, dx));
    double loy = Math.max(Math.min(ay, by), Math.min(cy, dy));
    double hiy = Math.min(Math.max(ay, by), Math.max(cy, dy));
    if (lox > hix || loy > hiy) return false;
    return hix - lox > 1e-9 || hiy - loy > 1e-9;
  }

  static boolean overlapsBoundary(Polygon p, double ax, double ay, double bx, double by) {
    List<Polygon> all = new ArrayList<>();
    all.add(p);
    for (Polygon h : p.getHoles()) {
      all.add(h);
    }
    for (Polygon poly : all) {
      double[] lats = poly.getPolyLats();
      double[] lons = poly.getPolyLons();
      for (int i = 1; i < lats.length; i++) {
        if (segmentsOverlap(lons[i - 1], lats[i - 1], lons[i], lats[i], ax, ay, bx, by)) {
          return true;
        }
      }
    }
    return false;
  }

  public static void main(String[] args) {
    double[] lats = new double[] {1.0, 2.0, 3.0, 1.0};
    double[] lons = new double[] {0.0, 0.5, 1.0, 0.0};
    Polygon p = new Polygon(lats, lons);
    List<Tessellator.Triangle> tess = Tessellator.tessellate(p, false);
    for (Tessellator.Triangle t : tess) {
      byte[] bytes = new byte[7 * 4];
      ShapeField.encodeTriangle(
          bytes,
          t.getEncodedY(0),
          t.getEncodedX(0),
          t.isEdgefromPolygon(0),
          t.getEncodedY(1),
          t.getEncodedX(1),
          t.isEdgefromPolygon(1),
          t.getEncodedY(2),
          t.getEncodedX(2),
          t.isEdgefromPolygon(2));
      ShapeField.DecodedTriangle dt = new ShapeField.DecodedTriangle();
