package org.apache.lucene.document;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import org.apache.lucene.geo.GeoEncodingUtils;
import org.apache.lucene.geo.Polygon;
import org.apache.lucene.geo.Tessellator;

/** evaluates candidate flag rules for LINE triangles against geometric ground truth */
public class Eval {

  static int orient(double ax, double ay, double bx, double by, double cx, double cy) {
    double v = (bx - ax) * (cy - ay) - (by - ay) * (cx - ax);
    if (Math.abs(v) < 1e-12) return 0;
    return v > 0 ? 1 : -1;
  }

  static boolean segmentsOverlap(
      double ax, double ay, double bx, double by, double cx, double cy, double dx, double dy) {
    if (orient(ax, ay, bx, by, cx, cy) != 0 || orient(ax, ay, bx, by, dx, dy) != 0) {
      return false;
    }
    double lox = Math.max(Math.min(ax, bx), Math.min(cx, dx));
    double hix = Math.min(Math.max(ax, bx), Math.max(cx, dx));
    double loy = Math.max(Math.min(ay, by), Math.min(cy, dy));
    double hiy = Math.min(Math.max(ay, by), Math.max(cy, dy));
    if (lox > hix || loy > hiy) return false;
    return hix - lox > 1e-9 || hiy - loy > 1e-9;
  }

  static boolean overlapsBoundary(Polygon p, double ax, double ay, double bx, double by) {
    List<Polygon> all = new ArrayList<>();
    all.add(p);
    for (Polygon h : p.getHoles()) {
      all.add(h);
    }
    for (Polygon poly : all) {
      double[] lats = poly.getPolyLats();
      double[] lons = poly.getPolyLons();
      for (int i = 1; i < lats.length; i++) {
        if (segmentsOverlap(lons[i - 1], lats[i - 1], lons[i], lats[i], ax, ay, bx, by)) {
          return true;
        }
      }
    }
    return false;
  }

  static Polygon randomPolygon(Random r) {
    int n = 6 + r.nextInt(10);
    double cx = (r.nextDouble() - 0.5) * 40;
    double cy = (r.nextDouble() - 0.5) * 80;
    double radius = 1 + r.nextDouble() * 5;
    List<double[]> pts = new ArrayList<>();
    for (int i = 0; i < n; i++) {
      double angle = r.nextDouble() * 2 * Math.PI;
      double rad = radius * (0.5 + r.nextDouble());
      double lon = cx + rad * Math.cos(angle);
      double lat = cy + rad * Math.sin(angle);
      pts.add(new double[] {lon, lat});
      if (r.nextInt(3) == 0) {
        int cluster = 1 + r.nextInt(3);
        double[] prev = pts.get(pts.size() - 1);
        double[] next;
        if (pts.size() > 1) {
          next = pts.get(pts.size() - 2);
        } else {
          next = new double[] {lon + rad * Math.cos(angle + 0.5), lat + rad * Math.sin(angle + 0.5)};
        }
        double dx = next[0] - prev[0];
        double dy = next[1] - prev[1];
        double len = Math.sqrt(dx * dx + dy * dy);
        dx /= len;
        dy /= len;
        for (int j = 1; j <= cluster; j++) {
          double step = j * r.nextDouble() * 1e-7;
          pts.add(new double[] {prev[0] + dx * step, prev[1] + dy * step});
        }
      }
    }
    double[] lats = new double[pts.size() + 1];
    double[] lons = new double[pts.size() + 1];
    for (int i = 0; i < pts.size(); i++) {
      lons[i] = pts.get(i)[0];
      lats[i] = pts.get(i)[1];
    }
    lons[pts.size()] = lons[0];
    lats[pts.size()] = lats[0];
    try {
      return new Polygon(lats, lons);
    } catch (Exception e) {
      return null;
    }
  }

  static final String[] RULES = {
    "ab", "bc", "ca", "ab||bc", "ab||ca", "bc||ca", "ab||bc||ca"
  };

  static boolean rule(String rule, boolean ab, boolean bc, boolean ca) {
    switch (rule) {
      case "ab":
        return ab;
      case "bc":
        return bc;
      case "ca":
        return ca;
      case "ab||bc":
        return ab || bc;
      case "ab||ca":
        return ab || ca;
      case "bc||ca":
        return bc || ca;
      case "ab||bc||ca":
        return ab || bc || ca;
    }
    throw new IllegalStateException();
  }

  public static void main(String[] args) {
    Random r = new Random(Long.parseLong(args[0]));
    int[] wrong = new int[RULES.length];
    int lines = 0;
    int underCur = 0;
    int overCur = 0;
    for (int i = 0; i < 20000; i++) {
      Polygon p = randomPolygon(r);
      if (p == null) continue;
      List<Tessellator.Triangle> tess;
      try {
        tess = Tessellator.tessellate(p, false);
      } catch (Exception e) {
        continue;
      }
      for (Tessellator.Triangle t : tess) {
        byte[] bytes = new byte[7 * 4];
        ShapeField.encodeTriangle(
            bytes,
            t.getEncodedY(0),
            t.getEncodedX(0),
            t.isEdgefromPolygon(0),
            t.getEncodedY(1),
            t.getEncodedX(1),
            t.isEdgefromPolygon(1),
            t.getEncodedY(2),
            t.getEncodedX(2),
            t.isEdgefromPolygon(2));
        ShapeField.DecodedTriangle dt = new ShapeField.DecodedTriangle();
        ShapeField.decodeTriangle(bytes, dt);
        boolean isABeq = dt.aX == dt.bX && dt.aY == dt.bY;
        boolean isACeq = dt.aX == dt.cX && dt.aY == dt.cY;
        boolean isBCeq = dt.bX == dt.cX && dt.bY == dt.cY;
        ShapeField.resolveTriangleType(dt);
        if (dt.type != ShapeField.DecodedTriangle.TYPE.LINE) continue;
        lines++;
        double ax = GeoEncodingUtils.decodeLongitude(dt.aX);
        double ay = GeoEncodingUtils.decodeLatitude(dt.aY);
        double bx = GeoEncodingUtils.decodeLongitude(dt.bX);
        double by = GeoEncodingUtils.decodeLatitude(dt.bY);
        boolean truth = overlapsBoundary(p, ax, ay, bx, by);
        if (dt.ab == false && truth) underCur++;
        if (dt.ab == true && !truth) overCur++;
        for (int k = 0; k < RULES.length; k++) {
          // for rules other than plain "ab", recompute candidate from ORIGINAL flags
          boolean cand;
          if (RULES[k].equals("ab")) {
            cand = dt.ab;
          } else {
            cand =
                rule(
                    RULES[k],
                    t.isEdgefromPolygon(0),
                    t.isEdgefromPolygon(1),
                    t.isEdgefromPolygon(2));
          }
          if (cand != truth) wrong[k]++;
        }
      }
    }
    System.out.println("LINE triangles=" + lines);
    System.out.println("current: undermarked=" + underCur + " overmarked=" + overCur);
    for (int k = 0; k < RULES.length; k++) {
      System.out.println("rule " + RULES[k] + ": wrong=" + wrong[k]);
    }
  }
}

