  static boolean rule(String name, String pattern, boolean ab, boolean bc, boolean ca) {
    switch (name) {
      case "current":
        return ab;
      case "nondeg2": // OR of the two non-degenerate edges
        switch (pattern) {
          case "ab":
            return bc || ca;
          case "ac":
            return ab || bc;
          case "bc":
            return ab || ca;
