          case "ab":
            return bc;
          case "ac":
            return bc;
          case "bc":
            return ca;
        }
        break;
      case "prev":
        switch (pattern) {
          case "ab":
            return ca;
          case "ac":
            return ab;
          case "bc":
            return ab;
        }
        break;
    }
    throw new IllegalStateException(name + " " + pattern);
  }

  static final String[] RULES = {"current", "nondeg2", "nondeg3", "next", "prev"};

  public static void main(String[] args) {
    Random r = new Random(Long.parseLong(args[0]));
    int[] wrong = new int[RULES.length];
