/**
 * End-to-end CONTAINS query check: index a polygon, then query with a line that crosses the
 * polygon boundary segment represented by LINE-type triangles; the polygon must not contain the
 * line. Uses multiple polygons and multiple candidate query lines.
 */
public class ContainsCheck {

  static double orientD(double ax, double ay, double bx, double by, double cx, double cy) {
    return (bx - ax) * (cy - ay) - (by - ay) * (cx - ax);
  }

  // returns true if polygon CONTAINS the line (using tessellation point checks on a dense sample)
  static boolean polygonContainsLine(Polygon p, Line line) {
    // the polygon contains the line only if every point of the line is inside.
    // we approximate by sampling; also endpoints must be inside and line must not cross boundary.
    for (int i = 0; i <= 100; i++) {
      double t = i / 100.0;
      double lon = line.getLon(0) + (line.getLon(1) - line.getLon(0)) * t;
      double lat = line.getLat(0) + (line.getLat(1) - line.getLat(0)) * t;
      if (!org.apache.lucene.geo.Tessellator.pointInPolygon(
          Tessellator.tessellate(p, false), lat, lon)) {
        return false;
      }
    }
    return true;
  }

  static boolean boundaryCrossingsDecoded(Polygon p, double ax, double ay, double bx, double by) {
    // does line (ax,ay)-(bx,by) cross the polygon boundary?
    for (Polygon poly : allRings(p)) {
      double[] lats = poly.getPolyLats();
      double[] lons = poly.getPolyLons();
      for (int i = 1; i < lats.length; i++) {
        if (org.apache.lucene.geo.GeoUtils.lineCrossesLineWithBoundary(
            ax, ay, bx, by, lons[i - 1], lats[i - 1], lons[i], lats[i])) {
          return true;
        }
      }
    }
    return false;
  }

  static List<Polygon> allRings(Polygon p) {
    List<Polygon> all = new ArrayList<>();
    all.add(p);
    for (Polygon h : p.getHoles()) {
      all.add(h);
    }
    return all;
  }

  /** index the polygon and run CONTAINS line query for the provided query line */
  static boolean containsMatches(Polygon p, Line queryLine) throws Exception {
    Directory dir = new RAMDirectory();
    IndexWriterConfig cfg = new IndexWriterConfig();
    IndexWriter w = new IndexWriter(dir, cfg);
    org.apache.lucene.document.Document doc = new org.apache.lucene.document.Document();
    for (org.apache.lucene.index.Field f : LatLonShape.createIndexableFields("geo", p)) {
      doc.add(f);
    }
    w.addDocument(doc);
    w.close();
    IndexReader reader = org.apache.lucene.index.DirectoryReader.open(dir);
    IndexSearcher searcher = new IndexSearcher(reader);
    Query q = LatLonShape.newLineQuery("geo", QueryRelation.CONTAINS, queryLine);
    ScoreDoc[] hits = searcher.search(q, 10).scoreDocs;
    reader.close();
    dir.close();
    return hits.length > 0;
