package org.apache.lucene.document;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import org.apache.lucene.document.ShapeField.QueryRelation;
import org.apache.lucene.geo.GeoEncodingUtils;
import org.apache.lucene.geo.GeoUtils;
import org.apache.lucene.geo.Line;
import org.apache.lucene.geo.Polygon;
import org.apache.lucene.geo.Tessellator;
import org.apache.lucene.index.DirectoryReader;
import org.apache.lucene.index.IndexReader;
import org.apache.lucene.index.IndexWriter;
import org.apache.lucene.index.IndexWriterConfig;
import org.apache.lucene.search.IndexSearcher;
import org.apache.lucene.search.Query;
import org.apache.lucene.search.ScoreDoc;
import org.apache.lucene.store.ByteBuffersDirectory;
import org.apache.lucene.store.Directory;

/**
 * End-to-end CONTAINS query check: index a polygon, then query with lines that cross the
 * polygon's boundary on a segment represented by a LINE-type triangle. Such lines are not
 * contained in the polygon, so CONTAINS must not match.
 */
public class ContainsCheck {

  static boolean boundaryCrossings(Polygon p, double alon, double alat, double blon, double blat) {
    for (Polygon poly : allRings(p)) {
      double[] lats = poly.getPolyLats();
      double[] lons = poly.getPolyLons();
      for (int i = 1; i < lats.length; i++) {
        if (GeoUtils.lineCrossesLineWithBoundary(
            alon, alat, blon, blat, lons[i - 1], lats[i - 1], lons[i], lats[i])) {
          return true;
        }
      }
    }
    return false;
  }

  static List<Polygon> allRings(Polygon p) {
    List<Polygon> all = new ArrayList<>();
    all.add(p);
    for (Polygon h : p.getHoles()) {
      all.add(h);
    }
    return all;
  }

  static boolean containsMatches(Polygon p, Line[] queryLines) throws Exception {
    Directory dir = new ByteBuffersDirectory();
    IndexWriterConfig cfg = new IndexWriterConfig();
    cfg.setCodec(new org.apache.lucene.codecs.lucene95.Lucene95Codec());
    IndexWriter w = new IndexWriter(dir, cfg);
    org.apache.lucene.document.Document doc = new org.apache.lucene.document.Document();
    for (org.apache.lucene.document.Field f : LatLonShape.createIndexableFields("geo", p)) {
      doc.add(f);
    }
    w.addDocument(doc);
    w.close();
    IndexReader reader = DirectoryReader.open(dir);
    IndexSearcher searcher = new IndexSearcher(reader);
    Query q = LatLonShape.newLineQuery("geo", QueryRelation.CONTAINS, queryLines);
    ScoreDoc[] hits = searcher.search(q, 10).scoreDocs;
    reader.close();
    dir.close();
    return hits.length > 0;
  }

  static boolean pointInside(Polygon p, double lat, double lon) {
    try {
      return Tessellator.pointInPolygon(Tessellator.tessellate(p, false), lat, lon);
    } catch (Exception e) {
      return false;
    }
  }

  static Polygon randomPolygon(Random r) {
    int n = 6 + r.nextInt(10);
    double cx = (r.nextDouble() - 0.5) * 40;
    double cy = (r.nextDouble() - 0.5) * 80;
    double radius = 1 + r.nextDouble() * 5;
    List<double[]> pts = new ArrayList<>();
    for (int i = 0; i < n; i++) {
      double angle = r.nextDouble() * 2 * Math.PI;
      double rad = radius * (0.5 + r.nextDouble());
      double lon = cx + rad * Math.cos(angle);
      double lat = cy + rad * Math.sin(angle);
      pts.add(new double[] {lon, lat});
      if (r.nextInt(3) == 0) {
        int cluster = 1 + r.nextInt(3);
        double[] prev = pts.get(pts.size() - 1);
        double[] next;
        if (pts.size() > 1) {
          next = pts.get(pts.size() - 2);
        } else {
          next = new double[] {lon + rad * Math.cos(angle + 0.5), lat + rad * Math.sin(angle + 0.5)};
        }
        double dx = next[0] - prev[0];
        double dy = next[1] - prev[1];
        double len = Math.sqrt(dx * dx + dy * dy);
        dx /= len;
        dy /= len;
        for (int j = 1; j <= cluster; j++) {
          double step = j * r.nextDouble() * 1e-7;
          pts.add(new double[] {prev[0] + dx * step, prev[1] + dy * step});
        }
      }
    }
    double[] lats = new double[pts.size() + 1];
    double[] lons = new double[pts.size() + 1];
    for (int i = 0; i < pts.size(); i++) {
      lons[i] = pts.get(i)[0];
      lats[i] = pts.get(i)[1];
    }
    lons[pts.size()] = lons[0];
    lats[pts.size()] = lats[0];
    try {
      return new Polygon(lats, lons);
    } catch (Exception e) {
      return null;
    }
  }

  public static void main(String[] args) throws Exception {
    Random r = new Random(Long.parseLong(args[0]));
    int falsePositives = 0;
    int checked = 0;
    for (int i = 0; i < 5000 && falsePositives < 3; i++) {
      Polygon p = randomPolygon(r);
      if (p == null) continue;
      List<Tessellator.Triangle> tess;
      try {
        tess = Tessellator.tessellate(p, false);
      } catch (Exception e) {
        continue;
      }
      List<Line> badLines = new ArrayList<>();
      for (Tessellator.Triangle t : tess) {
        byte[] bytes = new byte[7 * 4];
        ShapeField.encodeTriangle(
            bytes,
            t.getEncodedY(0),
            t.getEncodedX(0),
            t.isEdgefromPolygon(0),
            t.getEncodedY(1),
            t.getEncodedX(1),
            t.isEdgefromPolygon(1),
            t.getEncodedY(2),
            t.getEncodedX(2),
            t.isEdgefromPolygon(2));
        ShapeField.DecodedTriangle dt = new ShapeField.DecodedTriangle();
        ShapeField.decodeTriangle(bytes, dt);
        ShapeField.resolveTriangleType(dt);
        if (dt.type != ShapeField.DecodedTriangle.TYPE.LINE) continue;
        double alat = GeoEncodingUtils.decodeLatitude(dt.aY);
        double alon = GeoEncodingUtils.decodeLongitude(dt.aX);
        double blat = GeoEncodingUtils.decodeLatitude(dt.bY);
        double blon = GeoEncodingUtils.decodeLongitude(dt.bX);
        if (boundaryCrossings(p, alon, alat, blon, blat) == false) {
          continue;
        }
        // build query lines crossing this boundary segment transversally
        double mLat = (alat + blat) / 2;
        double mLon = (alon + blon) / 2;
        double dx = blat - alat;
        double dy = blon - alon;
        double len = Math.sqrt(dx * dx + dy * dy);
        double nLat = -dy / len;
        double nLon = dx / len;
        for (double outEps : new double[] {1e-4, 1e-2}) {
          for (double inEps : new double[] {1e-2, 0.5}) {
            for (int sign = -1; sign <= 1; sign += 2) {
              double lat1 = mLat + sign * nLat * outEps;
              double lon1 = mLon + sign * nLon * outEps;
              double lat2 = mLat - sign * nLat * inEps;
              double lon2 = mLon - sign * nLon * inEps;
              // truth: line is not contained if one endpoint is outside
              boolean out1 = pointInside(p, lat1, lon1);
              boolean out2 = pointInside(p, lat2, lon2);
              if (out1 == out2) {
                continue;
              }
              badLines.add(new Line(new double[] {lat1, lat2}, new double[] {lon1, lon2}));
            }
          }
        }
      }
      if (badLines.isEmpty()) continue;
      checked++;
      boolean matched = containsMatches(p, badLines.toArray(new Line[0]));
      if (matched) {
        falsePositives++;
        System.out.println(
            "FALSE POSITIVE: polygon=" + polygonStr(p) + " numBadLines=" + badLines.size());
      }
    }
    System.out.println("checkedPolygons=" + checked + " falsePositives=" + falsePositives);
  }

  static String polygonStr(Polygon p) {
    StringBuilder sb = new StringBuilder();
    double[] lats = p.getPolyLats();
    double[] lons = p.getPolyLons();
    for (int i = 0; i < lats.length; i++) {
      sb.append(lats[i]).append(",").append(lons[i]).append(" ");
    }
    return sb.toString();
  }
}

