package org.apache.lucene.document;

import java.util.ArrayList;
import java.util.List;
import org.apache.lucene.document.ShapeField.DecodedTriangle;
import org.apache.lucene.document.ShapeField.QueryRelation;
import org.apache.lucene.geo.GeoEncodingUtils;
import org.apache.lucene.geo.GeoUtils;
import org.apache.lucene.geo.Line;
import org.apache.lucene.geo.Polygon;
import org.apache.lucene.geo.Tessellator;

/** trace one failing polygon: which indexed triangle should have vetoed the query */
public class Trace {

  static final String POLY =
      "22.682327919368838,-11.076202016216302 22.965361280594855,-11.118196434917909 "
          + "24.888327178227033,-12.200434786754851 21.34299166007414,-12.424542030334994 "
          + "24.630509062130997,-13.368951767573495 24.58078074954861,-13.681656013393788 "
          + "24.141351712384363,-13.045065553923532 22.299965131804843,-10.35422520242811 "
          + "22.29996515221166,-10.354225232248833 22.299965191739773,-10.354225290011742 "
          + "22.299965243588726,-10.354225365779243 22.682327919368838,-11.076202016216302";

  static List<Polygon> allRings(Polygon p) {
    List<Polygon> all = new ArrayList<>();
    all.add(p);
    for (Polygon h : p.getHoles()) {
      all.add(h);
    }
    return all;
  }

  static boolean boundaryCrossings(Polygon p, double alon, double alat, double blon, double blat) {
    for (Polygon poly : allRings(p)) {
      double[] lats = poly.getPolyLats();
      double[] lons = poly.getPolyLons();
      for (int i = 1; i < lats.length; i++) {
        if (GeoUtils.lineCrossesLineWithBoundary(
            alon, alat, blon, blat, lons[i - 1], lats[i - 1], lons[i], lats[i])) {
          return true;
        }
      }
    }
    return false;
  }

  public static void main(String[] args) throws Exception {
    String[] parts = POLY.split(" ");
    double[] lats = new double[parts.length];
    double[] lons = new double[parts.length];
    for (int i = 0; i < parts.length; i++) {
      String[] ll = parts[i].split(",");
      lats[i] = Double.parseDouble(ll[0]);
      lons[i] = Double.parseDouble(ll[1]);
    }
    Polygon p = new Polygon(lats, lons);
    List<Tessellator.Triangle> tess = Tessellator.tessellate(p, false);
    System.out.println("num triangles=" + tess.size());
    List<double[]> lines = new ArrayList<>();
    for (Tessellator.Triangle t : tess) {
      byte[] bytes = new byte[7 * 4];
      ShapeField.encodeTriangle(
          bytes,
          t.getEncodedY(0),
          t.getEncodedX(0),
          t.isEdgefromPolygon(0),
          t.getEncodedY(1),
          t.getEncodedX(1),
          t.isEdgefromPolygon(1),
          t.getEncodedY(2),
          t.getEncodedX(2),
          t.isEdgefromPolygon(2));
      DecodedTriangle dt = new DecodedTriangle();
      ShapeField.decodeTriangle(bytes, dt);
      boolean isABeq = dt.aX == dt.bX && dt.aY == dt.bY;
      boolean isACeq = dt.aX == dt.cX && dt.aY == dt.cY;
      boolean isBCeq = dt.bX == dt.cX && dt.bY == dt.cY;
      ShapeField.resolveTriangleType(dt);
      if (dt.type != DecodedTriangle.TYPE.LINE) continue;
      double alat = GeoEncodingUtils.decodeLatitude(dt.aY);
      double alon = GeoEncodingUtils.decodeLongitude(dt.aX);
      double blat = GeoEncodingUtils.decodeLatitude(dt.bY);
      double blon = GeoEncodingUtils.decodeLongitude(dt.bX);
      if (boundaryCrossings(p, alon, alat, blon, blat) == false) continue;
      if (dt.ab) continue;
      System.out.println(
          "crossing LINE seg=("
              + alat
              + ","
              + alon
              + ")-("
              + blat
              + ","
              + blon
              + ") flags="
              + dt.ab
              + dt.bc
              + dt.ca
              + " raw="
              + t.isEdgefromPolygon(0)
              + t.isEdgefromPolygon(1)
              + t.isEdgefromPolygon(2)
              + " rawverts=("
              + t.getY(0)
              + ","
              + t.getX(0)
              + ")-("
              + t.getY(1)
              + ","
              + t.getX(1)
              + ")-("
              + t.getY(2)
              + ","
              + t.getX(2)
              + ")");
      lines.add(new double[] {alat, alon, blat, blon});
    }
    // for each bad line midpoint, build a crossing query line and check which triangles it
    // intersects
    for (double[] l : lines) {
      double alat = l[0], alon = l[1], blat = l[2], blon = l[3];
      double mLat = (alat + blat) / 2;
      double mLon = (alon + blon) / 2;
      double dx = blat - alat;
      double dy = blon - alon;
      double len = Math.sqrt(dx * dx + dy * dy);
      double nLat = -dy / len;
      double nLon = dx / len;
      double lat1 = mLat + nLat * 0.01;
      double lon1 = mLon + nLon * 0.01;
      double lat2 = mLat - nLat * 0.3;
      double lon2 = mLon - nLon * 0.3;
      Line ql = new Line(new double[] {lat1, lat2}, new double[] {lon1, lon2});
      System.out.println(
          "query line=("
              + lat1
              + ","
              + lon1
              + ")-("
              + lat2
              + ","
              + lon2
              + ") crossesBoundary="
              + boundaryCrossings(p, lon1, lat1, lon2, lat2));
      org.apache.lucene.geo.Component2D qc = LatLonGeometry.create(ql);
      for (Tessellator.Triangle t : tess) {
        byte[] bytes = new byte[7 * 4];
        ShapeField.encodeTriangle(
            bytes,
            t.getEncodedY(0),
            t.getEncodedX(0),
            t.isEdgefromPolygon(0),
            t.getEncodedY(1),
            t.getEncodedX(1),
            t.isEdgefromPolygon(1),
            t.getEncodedY(2),
            t.getEncodedX(2),
            t.isEdgefromPolygon(2));
        DecodedTriangle dt = new DecodedTriangle();
        ShapeField.decodeTriangle(bytes, dt);
        ShapeField.resolveTriangleType(dt);
        double ax = GeoEncodingUtils.decodeLongitude(dt.aX);
        double ay = GeoEncodingUtils.decodeLatitude(dt.aY);
        double bx = GeoEncodingUtils.decodeLongitude(dt.bX);
        double by = GeoEncodingUtils.decodeLatitude(dt.bY);
        double cx = GeoEncodingUtils.decodeLongitude(dt.cX);
        double cy = GeoEncodingUtils.decodeLatitude(dt.cY);
        org.apache.lucene.geo.Component2D.WithinRelation wr;
        switch (dt.type) {
          case LINE:
            wr = qc.withinLine(ax, ay, dt.ab, bx, by);
            break;
          case TRIANGLE:
            wr = qc.withinTriangle(ax, ay, dt.ab, bx, by, dt.bc, cx, cy, dt.ca);
            break;
          case POINT:
            wr = qc.withinPoint(ax, ay);
            break;
          default:
            wr = null;
        }
        // check if query line crosses any edge of this triangle geometrically
        boolean crossAB =
            GeoUtils.lineCrossesLineWithBoundary(lon1, lat1, lon2, lat2, ax, ay, bx, by);
        boolean crossBC =
            GeoUtils.lineCrossesLineWithBoundary(lon1, lat1, lon2, lat2, bx, by, cx, cy);
        boolean crossCA =
            GeoUtils.lineCrossesLineWithBoundary(lon1, lat1, lon2, lat2, cx, cy, ax, ay);
        if (wr != org.apache.lucene.geo.Component2D.WithinRelation.DISJOINT
            || crossAB
            || crossBC
            || crossCA) {
          System.out.println(
              "  tri type="
                  + dt.type
                  + " flags="
                  + dt.ab
                  + dt.bc
                  + dt.ca
                  + " within="
                  + wr
                  + " crossEdges="
                  + crossAB
                  + crossBC
                  + crossCA
                  + " rawtri="
                  + t.isEdgefromPolygon(0)
                  + t.isEdgefromPolygon(1)
                  + t.isEdgefromPolygon(2));
        }
      }
      break; // just first bad line
    }
  }
}

