package org.apache.lucene.document;

import org.apache.lucene.geo.GeoEncodingUtils;

/** verify flag mapping in encodeTriangle orientation swap */
public class SwapCheck {

  public static void main(String[] args) {
    // CW triangle: a=(0,0), b=(0,1), c=(1,0)
    int aX = GeoEncodingUtils.encodeLongitude(0);
    int aY = GeoEncodingUtils.encodeLatitude(0);
    int bX = GeoEncodingUtils.encodeLongitude(0);
    int bY = GeoEncodingUtils.encodeLatitude(1);
    int cX = GeoEncodingUtils.encodeLongitude(1);
    int cY = GeoEncodingUtils.encodeLatitude(0);
    int orient =
        (bX - aX) * (cY - aY) - (bY - aY) * (cX - aX) > 0 ? 1 : -1;
    System.out.println("input orient (positive=CCW): " + orient);
    byte[] bytes = new byte[7 * 4];
    // encodeTriangle takes (aY, aX, ab, bY, bX, bc, cY, cX, ca)
    ShapeField.encodeTriangle(bytes, aY, aX, true, bY, bX, true, cY, cX, false);
    ShapeField.DecodedTriangle dt = new ShapeField.DecodedTriangle();
    ShapeField.decodeTriangle(bytes, dt);
    System.out.println(
        "decoded verts: a=(lat "
            + GeoEncodingUtils.decodeLatitude(dt.aY)
            + ", lon "
            + GeoEncodingUtils.decodeLongitude(dt.aX)
            + ") b=(lat "
            + GeoEncodingUtils.decodeLatitude(dt.bY)
            + ", lon "
            + GeoEncodingUtils.decodeLongitude(dt.bX)
            + ") c=(lat "
            + GeoEncodingUtils.decodeLatitude(dt.cY)
            + ", lon "
            + GeoEncodingUtils.decodeLongitude(dt.cX)
            + ")");
    System.out.println(
        "decoded flags: ab=" + dt.ab + " bc=" + dt.bc + " ca=" + dt.ca);
    // physical mapping after swap (a,b,c)->(a,c,b): new_ab=old_ca, new_bc=old_bc, new_ca=old_ab
    System.out.println("expected flags per physical mapping: ab=false bc=true ca=true");
    System.out.println("flags per current encode code: ab=true(bc) bc=true ca=true(ab)");
  }
}

