package org.apache.lucene.document;

import org.apache.lucene.geo.Polygon;
import org.apache.lucene.geo.Tessellator;

/** trace tessellation of one polygon with instrumented shadow Tessellator */
public class TessTrace {

  static final String POLY =
      "22.682327919368838,-11.076202016216302 22.965361280594855,-11.118196434917909 "
          + "24.888327178227033,-12.200434786754851 21.34299166007414,-12.424542030334994 "
          + "24.630509062130997,-13.368951767573495 24.58078074954861,-13.681656013393788 "
          + "24.141351712384363,-13.045065553923532 22.299965131804843,-10.35422520242811 "
          + "22.29996515221166,-10.354225232248833 22.299965191739773,-10.354225290011742 "
          + "22.299965243588726,-10.354225365779243 22.682327919368838,-11.076202016216302";

  public static void main(String[] args) throws Exception {
    String[] parts = POLY.split(" ");
    double[] lats = new double[parts.length];
    double[] lons = new double[parts.length];
    for (int i = 0; i < parts.length; i++) {
      String[] ll = parts[i].split(",");
      lats[i] = Double.parseDouble(ll[0]);
      lons[i] = Double.parseDouble(ll[1]);
    }
    Polygon p = new Polygon(lats, lons);
    Tessellator.Monitor monitor =
        new Tessellator.Monitor() {
          public void currentState(String status, java.util.List<org.apache.lucene.geo.Point> points, java.util.List<Tessellator.Triangle> tessellation) {
            System.out.println("STATE " + status + " nodes=" + points + " tris=" + tessellation.size());
            for (Tessellator.Triangle t : tessellation) {
              System.out.println(
                  "   tri v=("
                      + t.getY(0)
                      + ","
                      + t.getX(0)
                      + ")-("
                      + t.getY(1)
                      + ","
                      + t.getX(1)
                      + ")-("
                      + t.getY(2)
                      + ","
                      + t.getX(2)
                      + ") flags="
                      + t.isEdgefromPolygon(0)
                      + t.isEdgefromPolygon(1)
                      + t.isEdgefromPolygon(2));
            }
          }

          public void startSplit(String status, java.util.List<org.apache.lucene.geo.Point> left, java.util.List<org.apache.lucene.geo.Point> right) {
            System.out.println("SPLIT " + status + " L=" + left + " R=" + right);
          }

          public void endSplit(String status) {
            System.out.println("ENDSPLIT " + status);
          }
        };
    java.util.List<Tessellator.Triangle> tess = Tessellator.tessellate(p, false, monitor);
    System.out.println("final triangles=" + tess.size());
    for (Tessellator.Triangle t : tess) {
      System.out.println(
          "FINAL v0idx? v=("
              + t.getY(0)
              + ","
              + t.getX(0)
              + ")-("
              + t.getY(1)
              + ","
              + t.getX(1)
              + ")-("
              + t.getY(2)
              + ","
              + t.getX(2)
              + ") flags="
              + t.isEdgefromPolygon(0)
              + t.isEdgefromPolygon(1)
              + t.isEdgefromPolygon(2));
    }
  }
}

