package org.apache.lucene.document;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import org.apache.lucene.document.ShapeField.QueryRelation;
import org.apache.lucene.geo.Line;
import org.apache.lucene.geo.Polygon;
import org.apache.lucene.geo.Tessellator;
import org.apache.lucene.index.DirectoryReader;
import org.apache.lucene.index.IndexReader;
import org.apache.lucene.index.IndexWriter;
import org.apache.lucene.index.IndexWriterConfig;
import org.apache.lucene.search.IndexSearcher;
import org.apache.lucene.search.Query;
import org.apache.lucene.search.ScoreDoc;
import org.apache.lucene.store.ByteBuffersDirectory;
import org.apache.lucene.store.Directory;

/**
 * End-to-end CONTAINS correctness: for every ring edge of the indexed polygon (outer and holes),
 * query with lines crossing that edge (truth: not contained) and with lines fully inside (truth:
 * contained). CONTAINS must agree.
 */
public class EdgeCheck {

  static boolean containsMatches(Polygon p, Line[] queryLines) throws Exception {
    Directory dir = new ByteBuffersDirectory();
    IndexWriterConfig cfg = new IndexWriterConfig();
    cfg.setCodec(new org.apache.lucene.codecs.lucene95.Lucene95Codec());
    IndexWriter w = new IndexWriter(dir, cfg);
    org.apache.lucene.document.Document doc = new org.apache.lucene.document.Document();
    for (org.apache.lucene.document.Field f : LatLonShape.createIndexableFields("geo", p)) {
      doc.add(f);
    }
    w.addDocument(doc);
    w.close();
    IndexReader reader = DirectoryReader.open(dir);
    IndexSearcher searcher = new IndexSearcher(reader);
    Query q = LatLonShape.newLineQuery("geo", QueryRelation.CONTAINS, queryLines);
    ScoreDoc[] hits = searcher.search(q, 10).scoreDocs;
    reader.close();
    dir.close();
    return hits.length > 0;
  }

  static boolean pointInside(Polygon p, double lat, double lon) {
    try {
      return Tessellator.pointInPolygon(Tessellator.tessellate(p, false), lat, lon);
    } catch (Exception e) {
      return false;
    }
  }

  static Polygon randomPolygon(Random r) {
    int n = 6 + r.nextInt(10);
    double cx = (r.nextDouble() - 0.5) * 40;
    double cy = (r.nextDouble() - 0.5) * 80;
    double radius = 1 + r.nextDouble() * 5;
    List<double[]> pts = new ArrayList<>();
    for (int i = 0; i < n; i++) {
      double angle = r.nextDouble() * 2 * Math.PI;
      double rad = radius * (0.5 + r.nextDouble());
      double lon = cx + rad * Math.cos(angle);
      double lat = cy + rad * Math.sin(angle);
      pts.add(new double[] {lon, lat});
      if (r.nextInt(3) == 0 && pts.size() > 1) {
        double[] prev = pts.get(pts.size() - 2);
        double dx = pts.get(pts.size() - 1)[0] - prev[0];
        double dy = pts.get(pts.size() - 1)[1] - prev[1];
        double len = Math.sqrt(dx * dx + dy * dy);
        dx /= len;
        dy /= len;
        int cluster = 1 + r.nextInt(3);
        double back = r.nextDouble() * 1e-6;
        for (int j = 1; j <= cluster; j++) {
          double t = back * j / cluster;
          pts.add(
              new double[] {
                pts.get(pts.size() - 1)[0] - dx * t, pts.get(pts.size() - 1)[1] - dy * t
              });
        }
      }
    }
    double[] lats = new double[pts.size() + 1];
    double[] lons = new double[pts.size() + 1];
    for (int i = 0; i < pts.size(); i++) {
      lons[i] = pts.get(i)[0];
      lats[i] = pts.get(i)[1];
    }
    lons[pts.size()] = lons[0];
    lats[pts.size()] = lats[0];
    try {
      Polygon outer = new Polygon(lats, lons);
      if (r.nextInt(2) == 0) {
        List<double[]> hpts = new ArrayList<>();
        int hn = 5 + r.nextInt(4);
        double hr = radius * 0.3;
        for (int i = 0; i < hn; i++) {
          double angle = r.nextDouble() * 2 * Math.PI;
          double lon = cx + hr * Math.cos(angle);
          double lat = cy + hr * Math.sin(angle);
          hpts.add(new double[] {lon, lat});
          if (r.nextInt(3) == 0 && hpts.size() > 1) {
            double[] prev = hpts.get(hpts.size() - 2);
            double dx = hpts.get(hpts.size() - 1)[0] - prev[0];
            double dy = hpts.get(hpts.size() - 1)[1] - prev[1];
            double len = Math.sqrt(dx * dx + dy * dy);
            dx /= len;
            dy /= len;
            int cluster = 1 + r.nextInt(3);
            double back = r.nextDouble() * 1e-6;
            for (int j = 1; j <= cluster; j++) {
              double t = back * j / cluster;
              hpts.add(
                  new double[] {
                    hpts.get(hpts.size() - 1)[0] - dx * t, hpts.get(hpts.size() - 1)[1] - dy * t
                  });
            }
          }
        }
        double[] hlats = new double[hpts.size() + 1];
        double[] hlons = new double[hpts.size() + 1];
        for (int i = 0; i < hpts.size(); i++) {
          hlons[i] = hpts.get(i)[0];
          hlats[i] = hpts.get(i)[1];
        }
        hlons[hpts.size()] = hlons[0];
        hlats[hpts.size()] = hlats[0];
        try {
          Polygon hole = new Polygon(hlats, hlons);
          return new Polygon(lats, lons, hole);
        } catch (Exception e) {
          return outer;
        }
      }
      return outer;
    } catch (Exception e) {
      return null;
    }
  }

  public static void main(String[] args) throws Exception {
    Random r = new Random(Long.parseLong(args[0]));
    int iterations = Integer.parseInt(args[1]);
    int falsePositives = 0;
    int falseNegatives = 0;
    int checked = 0;
    for (int i = 0; i < iterations; i++) {
      Polygon p = randomPolygon(r);
      if (p == null) continue;
      try {
        Tessellator.tessellate(p, true);
      } catch (Exception e) {
        continue;
      }
      List<Line> crossLines = new ArrayList<>();
      List<Line> insideLines = new ArrayList<>();
      List<Polygon> rings = new ArrayList<>();
      rings.add(p);
      for (Polygon h : p.getHoles()) {
        rings.add(h);
      }
      for (Polygon poly : rings) {
        double[] lats = poly.getPolyLats();
        double[] lons = poly.getPolyLons();
        for (int e = 1; e < lats.length; e++) {
          double lat1 = lats[e - 1];
          double lon1 = lons[e - 1];
          double lat2 = lats[e];
          double lon2 = lons[e];
          double len = Math.sqrt((lat2 - lat1) * (lat2 - lat1) + (lon2 - lon1) * (lon2 - lon1));
          if (len < 1e-4) continue;
          double nLat = -(lon2 - lon1) / len;
          double nLon = (lat2 - lat1) / len;
          for (double frac : new double[] {0.25, 0.5, 0.75}) {
            double mLat = lat1 + (lat2 - lat1) * frac;
            double mLon = lon1 + (lon2 - lon1) * frac;
            for (double outEps : new double[] {1e-5, 1e-2}) {
              for (double inEps : new double[] {0.05, 0.5}) {
                for (int sign = -1; sign <= 1; sign += 2) {
                  double qLat1 = mLat + sign * nLat * outEps;
                  double qLon1 = mLon + sign * nLon * outEps;
                  double qLat2 = mLat - sign * nLat * inEps;
                  double qLon2 = mLon - sign * nLon * inEps;
                  boolean in1 = pointInside(p, qLat1, qLon1);
                  boolean in2 = pointInside(p, qLat2, qLon2);
                  if (in1 == in2) continue;
                  crossLines.add(new Line(new double[] {qLat1, qLat2}, new double[] {qLon1, qLon2}));
                }
              }
            }
          }
        }
      }
      // interior lines
      double cLat = 0;
      double cLon = 0;
      for (int k = 0; k < lats.length - 1; k++) {
        cLat += lats[k];
        cLon += lons[k];
      }
      cLat /= (lats.length - 1);
      cLon /= (lons.length - 1);
      for (int ang = 0; ang < 8; ang++) {
        double th = ang * Math.PI / 4;
        double qLat1 = cLat + 0.001 * Math.sin(th);
        double qLon1 = cLon + 0.001 * Math.cos(th);
        double qLat2 = cLat + 0.3 * Math.sin(th + 1.3);
        double qLon2 = cLon + 0.3 * Math.cos(th + 1.3);
        if (pointInside(p, qLat1, qLon1)
            && pointInside(p, qLat2, qLon2)
            && holesNotCrossed(p, qLat1, qLon1, qLat2, qLon2)) {
          insideLines.add(new Line(new double[] {qLat1, qLat2}, new double[] {qLon1, qLon2}));
        }
      }
      if (crossLines.isEmpty() && insideLines.isEmpty()) continue;
      checked++;
      if (crossLines.isEmpty() == false) {
        boolean matched = containsMatches(p, crossLines.toArray(new Line[0]));
        if (matched) {
          falsePositives++;
          System.out.println("FALSE POSITIVE: polygon=" + polygonStr(p));
        }
      }
      if (insideLines.isEmpty() == false) {
        boolean matched = containsMatches(p, insideLines.toArray(new Line[0]));
        if (matched == false) {
          falseNegatives++;
          System.out.println("FALSE NEGATIVE: polygon=" + polygonStr(p));
        }
      }
    }
    System.out.println(
        "checkedPolygons="
            + checked
            + " falsePositives="
            + falsePositives
            + " falseNegatives="
            + falseNegatives);
  }

  // line must not cross any ring (else it's not contained even with both endpoints inside)
  static boolean holesNotCrossed(Polygon p, double la1, double lo1, double la2, double lo2) {
    for (Polygon poly : allRings(p)) {
      double[] lats = poly.getPolyLats();
      double[] lons = poly.getPolyLons();
      for (int e = 1; e < lats.length; e++) {
        if (org.apache.lucene.geo.GeoUtils.lineCrossesLineWithBoundary(
            lo1, la1, lo2, la2, lons[e - 1], lats[e - 1], lons[e], lats[e])) {
          return false;
        }
      }
    }
    return true;
  }

  static List<Polygon> allRings(Polygon p) {
    List<Polygon> all = new ArrayList<>();
    all.add(p);
    for (Polygon h : p.getHoles()) {
      all.add(h);
    }
    return all;
  }

  static String polygonStr(Polygon p) {
    StringBuilder sb = new StringBuilder();
    double[] lats = p.getPolyLats();
    double[] lons = p.getPolyLons();
    for (int i = 0; i < lats.length; i++) {
      sb.append(lats[i]).append(",").append(lons[i]).append(" ");
    }
    return sb.toString();
  }
}

